#pragma once
#include <memory>
#include <vector>
struct Entry{int id,millidegrees;bool operator==(const Entry&)const=default;};
class ReportSnapshot{
 std::unique_ptr<std::vector<Entry>> state_;
public:
 ReportSnapshot();~ReportSnapshot()=default;
 ReportSnapshot(const ReportSnapshot&)=delete;ReportSnapshot&operator=(const ReportSnapshot&)=delete;
 ReportSnapshot(ReportSnapshot&&)noexcept=default;ReportSnapshot&operator=(ReportSnapshot&&)noexcept=default;
 const std::vector<Entry>& entries()const;
 void replace(const std::vector<Entry>& batch); // invalid_argument on invalid batch
};

#include "model.hpp"
#include <algorithm>
#include <set>
#include <stdexcept>
ReportSnapshot::ReportSnapshot():state_(std::make_unique<std::vector<Entry>>()){}
const std::vector<Entry>& ReportSnapshot::entries()const{static const std::vector<Entry> empty;return state_?*state_:empty;}
void ReportSnapshot::replace(const std::vector<Entry>& batch){if(!state_)state_=std::make_unique<std::vector<Entry>>();state_->clear();std::set<int> seen;for(const auto&e:batch){if(e.id<1||e.id>1000||e.millidegrees<-50000||e.millidegrees>150000||!seen.insert(e.id).second||state_->size()>=200)throw std::invalid_argument("batch");state_->push_back(e);}std::sort(state_->begin(),state_->end(),[](const Entry&a,const Entry&b){return a.id<b.id;});}

#include "model.hpp"
#include <iostream>
int main(){std::cout<<"Run public_tests; repair transactional replacement.\n";}

#include "model.hpp"
#include <stdexcept>
#include <iostream>
#include <algorithm>
void check(bool x,const char*why){if(!x)throw std::runtime_error(why);}
int main(){try{
ReportSnapshot model;model.replace({{9,30},{1,20}});auto before=model.entries();check(before==std::vector<Entry>{{1,20},{9,30}},"sorted pairs");
for(const auto&bad:std::vector<std::vector<Entry>>{{{2,1},{2,3}},{{2,1},{3,-50001}},{{2,1},{3,150001}},std::vector<Entry>(201,{1,1})}){bool caught=false;try{model.replace(bad);}catch(const std::invalid_argument&){caught=true;}check(caught,"bad batch accepted");check(model.entries()==before,"strong guarantee broken");}
ReportSnapshot moved=std::move(model);check(moved.entries()==before,"move lost data");model.replace({{8,1}});check(model.entries()==std::vector<Entry>{{8,1}},"moved-from object cannot be reused");check(moved.entries()==before,"owners share state");moved.replace({});check(moved.entries().empty(),"empty replacement");
std::cout<<"Public contract: PASS\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
